        case .writeResource(let path, let content):
            try c.encode("writeResource", forKey: .kind)
            try c.encode(path, forKey: .path)
            try c.encode(content, forKey: .content)
        case .getSettings:
            try c.encode("getSettings", forKey: .kind)
        case .saveSettings(let json):
            try c.encode("saveSettings", forKey: .kind)
            try c.encode(json, forKey: .json)
        case .mcpServers:
            try c.encode("mcpServers", forKey: .kind)
        case .mcpSave(let server):
            try c.encode("mcpSave", forKey: .kind)
            try c.encode(server, forKey: .server)
        case .mcpDelete(let name):
            try c.encode("mcpDelete", forKey: .kind)
            try c.encode(name, forKey: .name)
        case .plugins:
            try c.encode("plugins", forKey: .kind)
        case .setPluginEnabled(let pluginId, let enabled):
            try c.encode("setPluginEnabled", forKey: .kind)
            try c.encode(pluginId, forKey: .pluginId)
            try c.encode(enabled, forKey: .enabled)
        }
    }
}

public enum ConfigResponse: Codable, Equatable, Sendable {
    case snapshot(config: ConfigSnapshot)
    case resources(items: [ResourceItem])
    case resourceContent(content: String, format: ResourceFormat)
    case dirEntries(entries: [ConfigDirEntry])
    case settingsJson(json: String)
    case mcpServers(servers: [McpServerView])
    case plugins(items: [PluginView])
    case saved
    case rejected(code: String, message: String)

    private enum CodingKeys: String, CodingKey {
        case kind
        case config
        case items
        case content
        case format
        case entries
        case json
        case servers
        case code
        case message
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let kind = try c.decode(String.self, forKey: .kind)
        switch kind {
        case "snapshot":
            self = .snapshot(
                config: try c.decode(ConfigSnapshot.self, forKey: .config)
            )
        case "resources":
            self = .resources(
                items: try c.decode([ResourceItem].self, forKey: .items)
            )
        case "resourceContent":
            self = .resourceContent(
                content: try c.decode(String.self, forKey: .content),
                format: try c.decode(ResourceFormat.self, forKey: .format)
            )
        case "dirEntries":
            self = .dirEntries(
                entries: try c.decode([ConfigDirEntry].self, forKey: .entries)
            )
        case "settingsJson":
            self = .settingsJson(
                json: try c.decode(String.self, forKey: .json)
            )
        case "mcpServers":
            self = .mcpServers(
                servers: try c.decode([McpServerView].self, forKey: .servers)
            )
        case "plugins":
            self = .plugins(
                items: try c.decode([PluginView].self, forKey: .items)
            )
        case "saved":
            self = .saved
        case "rejected":
            self = .rejected(
                code: try c.decode(String.self, forKey: .code),
                message: try c.decode(String.self, forKey: .message)
            )
        default:
            throw DecodingError.dataCorruptedError(forKey: .kind, in: c, debugDescription: "unknown kind: \(kind)")
        }
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .snapshot(let config):
            try c.encode("snapshot", forKey: .kind)
            try c.encode(config, forKey: .config)
        case .resources(let items):
            try c.encode("resources", forKey: .kind)
            try c.encode(items, forKey: .items)
        case .resourceContent(let content, let format):
            try c.encode("resourceContent", forKey: .kind)
            try c.encode(content, forKey: .content)
            try c.encode(format, forKey: .format)
        case .dirEntries(let entries):
            try c.encode("dirEntries", forKey: .kind)
            try c.encode(entries, forKey: .entries)
        case .settingsJson(let json):
            try c.encode("settingsJson", forKey: .kind)
            try c.encode(json, forKey: .json)
        case .mcpServers(let servers):
            try c.encode("mcpServers", forKey: .kind)
            try c.encode(servers, forKey: .servers)
        case .plugins(let items):
            try c.encode("plugins", forKey: .kind)
            try c.encode(items, forKey: .items)
        case .saved:
            try c.encode("saved", forKey: .kind)
        case .rejected(let code, let message):
            try c.encode("rejected", forKey: .kind)
            try c.encode(code, forKey: .code)
            try c.encode(message, forKey: .message)
        }
    }
}
